# Async iterator pattern:
async for event in client.stream_chat(conversation_id, messages):
    if event.type == 'token':
        print(event.text, end='', flush=True)
    elif event.type == 'function_start':
        current_fn = event.name
    elif event.type == 'function_append':
        fn_buffer.append(event.text)
    elif event.type == 'done':
        break

# Callback pattern:
def on_token(e):
    sys.stdout.write(e.text)

def on_done(e):
    print('
DONE')

client.stream_chat_with_callbacks(messages, on_event={ 'token': on_token, 'done': on_done })

# Safe retry helper (context manager) that guarantees downstream sees each event at most once:
with client.safe_stream(messages, idempotency_key='signup-123') as stream:
    for event in stream:
        if event.type == 'token':
            write_to_output(event.text)
# Under the hood safe_stream buffers a tail and will re-emit only missing event_index ranges after a transient failure.
